mapper.select:
SELECT t.id, t.plate_no, t.frame_no, t.ic_card_no, t.company_id, t.axle_num, t.status, t.create_time, c.name AS companyName FROM tractor t LEFT JOIN transport_company c ON c.id = t.company_id
AND t.plate_no LIKE CONCAT('%', #{plateNo}, '%')
AND t.ic_card_no LIKE CONCAT('%', #{icCardNo}, '%')
AND t.company_id = #{companyId}
ORDER BY t.id ASC LIMIT #{offset}, #{size}

mapper.update:
UPDATE tractor
plate_no = #{plateNo}, frame_no = #{frameNo}, ic_card_no = #{icCardNo}, company_id = #{companyId}, axle_num = #{axleNum}, status = #{status},
WHERE id = #{id}
